(x, y, t) => {
  const cx = 240, cy = 120;
  const wx1 = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx2 = Math.sin(x*0.035-t*0.5)*8 + Math.cos(y*0.028+t*0.4)*6;
  const wy2 = Math.cos(y*0.032+t*0.45)*8 + Math.sin(x*0.025-t*0.55)*6;
  const sx = x + wx1 + wx2, sy = y + wy1 + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.75+4)*40, 0.085, 1.8, 1.05],
    [200+Math.sin(t*0.38+6)*110, 220+Math.cos(t*0.48+3)*70, 0.095, 2.4, 0.9]
  ];
  let aS = 0, iS = 0, dS = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    dS += Math.sin(d*f*0.4 - t*sp*0.3 + 2.8) * w;
  }
  const n = src.length, act = aS/n, inh = iS/n, dif = dS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07+t*1.5)*Math.sin(sy*0.06-t*1.2)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.3
    + (Math.sin(dist*0.08+ang*2-t*2.0) + Math.sin(dist*0.06-ang*5+t*1.8))*0.15;
  const turb = Math.sin(sx*0.2+Math.sin(sy*0.15+t)*2+t*1.5)*0.1
    + Math.sin(sy*0.18+Math.sin(sx*0.12-t)*1.5-t*1.2)*0.1;
  const micro = Math.sin(sx*0.35+t*3)*Math.sin(sy*0.32-t*2.5)*0.06
    + Math.sin((sx*0.4+sy*0.35)*0.5+t*4)*0.04;
  const rd1 = act - inh*0.7 + bg*0.3 + spiral;
  const rd2 = dif*0.5 + act*inh*0.3 + turb;
  const reaction = Math.tanh((rd1 + rd2*0.3 + micro)*2.2);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)
    + Math.sin((sx+sy)*0.1+t)*0.5
    + Math.sin(sx*0.08-t*0.8)*Math.cos(sy*0.09+t*0.6)*0.3)*1.5)*0.3;
  const blend = reaction*0.7 + cell*0.3, v = blend*0.5+0.5;
  const vig = 1.0 - Math.pow(Math.sqrt((x-cx)**2+(y-cy)**2)/320, 2)*0.15;
  const pal = [
    [5,10,45],[12,45,88],[18,95,122],[32,142,128],[78,168,108],
    [140,175,75],[195,175,55],[215,135,50],[205,90,55],[165,48,62],
    [105,25,58],[55,14,50],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = (0.85 + Math.sin(reaction*Math.PI)*0.15 + Math.abs(reaction)*0.05)*vig;
  const edge = Math.abs(reaction)>0.7?1.12:Math.abs(reaction)>0.5?1.05:1.0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge)|0
  ];
}
